steps.run:
VERSION="${GITHUB_REF#refs/tags/}"
echo "Creating release for version: $VERSION"

# Extract changelog section for this version
# This awk script extracts content between ## VERSION and the next ## line
CHANGELOG=$(awk -v version="$VERSION" '
  /^## / {
    if (found) exit;
    if ($2 == version) found=1;
    next;
  }
  found { print }
' CHANGELOG.md)

if [ -z "$CHANGELOG" ]; then
  echo "No changelog entry found for version $VERSION"
  exit 1
fi

# Save changelog to file (multiline output)
echo "$CHANGELOG" > /tmp/changelog.txt
echo "changelog_file=/tmp/changelog.txt" >> $GITHUB_OUTPUT

version=$(cat package.json | jq -r .version)
payload=$(jq --null-input --arg version "$version" '{
  "event_type": "open-release-pull-request",
  "client_payload": {
    "project": "DASHBOARD",
    "environment": "SANDBOX",
    "version": $version
  }
}')

gh api /repos/saleor/saleor-cloud-deployments/dispatches --input - <<< "$payload"

with.message:
🎉 New Issue Labeled with "Help Wanted" in Saleor Dashboard

**Issue Details:**
- Title: ${{ github.event.issue.title }}
- Number: #${{ github.event.issue.number }}
- URL: ${{ github.event.issue.html_url }}

Please take a look and help if you can! 🙏

steps.run:
export GITHUB_TOKEN=$( \
  curl --request GET --url "$VAULT_URL" --header "Authorization: JWT $VAULT_JWT" | jq -r .token \
)
payload=$(
  jq --arg version "$VERSION" -n '{
    "event_type": "open-release-pull-request",
    "client_payload": {
      "project": "DASHBOARD",
      "environment": "SANDBOX",
      "version": $version
    }
  }'
)
gh api /repos/saleor/saleor-cloud-deployments/dispatches --input <(echo "$payload")
